    "name": "editor-new-network.yaml",
    "text": "# netatlas test fixture: a model created with \"New\" in the editor and built up\n# with the editor operations (generated by scripts/make-fixtures.mjs).\nnetatlas: 1\ntitle: \"Lab: two edge routers\"\ndescription: \"Created in the netatlas editor: loopbacks, ports, a subinterface and a tunnel interface per router, one cable, IP networks, iBGP and a GRE tunnel between loopbacks.\"\ndevices:\n  - id: edge-a\n    type: router\n    router_id: lo0\n    protocols:\n      bgp: {asn: 65000}\n    interfaces:\n      - {id: ge-0/0/0, ip: [192.0.2.1/31]}\n    logical_interfaces:\n      - {id: lo0, type: loopback, label: Router ID, ip: [10.255.0.1/32]}\n      - {id: lo1, type: loopback, label: BGP source (IPv6), ip: [2001:db8:ffff::a/128]}\n      - {id: ge-0/0/0.100, type: virtual, label: Management, ip: [10.100.0.1/24]}\n      - {id: gr-0/0/0.1, type: tunnel, ip: [172.16.0.1/30], source: lo0, destination: 10.255.0.2}\n  - id: edge-b\n    label: Edge B\n    type: router\n    router_id: lo0\n    protocols:\n      bgp: {asn: 65000}\n    interfaces:\n      - {id: ge-0/0/0, ip: [192.0.2.0/31]}\n    logical_interfaces:\n      - {id: lo0, type: loopback, label: Router ID, ip: [10.255.0.2/32, 2001:db8:ffff::2/128]}\n      - {id: lo1, type: loopback, label: BGP source (IPv6), ip: [2001:db8:ffff::b/128]}\n      - {id: ge-0/0/0.100, type: virtual, label: Management, ip: [10.100.0.2/24]}\n      - {id: gr-0/0/0.1, type: tunnel, ip: [172.16.0.2/30], source: lo0, destination: 10.255.0.1}\nlinks:\n  - {id: cable-1, a: edge-a:ge-0/0/0, b: edge-b:ge-0/0/0, medium: fiber, speed: 10G, cable: LC-LC OM4 3m}\nnetworks:\n  - id: net-core\n    label: Core link\n    cidr: 192.0.2.0/31\n  - id: net-mgmt\n    label: Management\n    cidr: 10.100.0.0/24\n    vlan: 100\n  - id: net-loopbacks\n    label: Router loopbacks\n    cidr: 10.255.0.0/24\nrelations:\n  - id: ibgp-v6\n    protocol: ibgp\n    endpoints: [edge-a:lo1, edge-b:lo1]\n    over: cable-1\n    attrs:\n      address-family: [ipv6-unicast, evpn]\n  - id: gre-lab\n    protocol: gre\n    endpoints: [edge-a:lo0, edge-b:lo0]\n    over: cable-1\n    attrs:\n      key: 100\n      keepalive:\n        interval: 10s\n        retries: 3\n\nlayout:\n  physical:\n    edge-a: [75, 65]\n    edge-b: [491, 65]\n  logical:\n    edge-a: [456, 309]\n    edge-b: [91, 350]\n    net-core: [117, 611]\n    net-loopbacks: [512, 562]\n    net-mgmt: [226, 21]\n"
